INSERT INTO tsc_categories (id, name, accents) VALUES
(1, 'Care and Clinical', '["under direct supervision","within scope of practice","for complex or atypical presentations","for a service or ward","across a care network","advancing clinical practice"]'),
(2, 'Commercial and Customer', '["on defined accounts or transactions","within agreed commercial terms","in contested or high-value situations","for a portfolio or market","for the commercial strategy","shaping how the market operates"]'),
(3, 'Data and Analytics', '["on prepared datasets","against agreed data quality rules","where sources conflict or are incomplete","across the function’s data estate","as an enterprise data capability","as a national or industry data practice"]'),
(4, 'Design and Content', '["to a supplied brief","within an established system","where the brief is unclear or contested","across a product or portfolio","across the brand and portfolio","defining practice others follow"]'),
(5, 'Engineering and Technical', '["on components under supervision","to specification","where specification is incomplete","for a system or asset class","across the asset portfolio","advancing engineering practice"]'),
(6, 'Governance and Assurance', '["completing prescribed checks","applying the control framework","where judgement on materiality is needed","over a control domain","over the assurance framework","influencing regulatory expectation"]'),
(7, 'Learning and Development', '["delivering prepared material","for a defined programme","where learner needs vary widely","across a curriculum","across the learning strategy","shaping adult learning practice"]'),
(8, 'Operations and Delivery', '["on a single shift or task","for a defined process","when the process breaks down","across an operating unit","across the operating model","setting the benchmark for the sector"]'),
(9, 'People and Organisation', '["for individual cases","for a defined population","where policy and practice conflict","for a business unit","for the whole organisation","shaping national practice"]'),
(10, 'Security and Resilience', '["following a runbook","against a defined control set","where the threat is novel","across the control environment","as an enterprise risk posture","shaping sector-wide standards"]'),
(11, 'Software and Platforms', '["on well-specified tickets","within an existing service","across services with shared dependencies","for a platform used by other teams","across the engineering organisation","as reference practice for the industry"]'),
(12, 'Sustainability and Compliance', '["collecting prescribed evidence","against a recognised standard","where methodology must be selected and defended","across a reporting boundary","across the enterprise and value chain","contributing to standard-setting bodies"]');
