INSERT INTO tsc_levels (id, tsc_id, level, level_name, descriptor, autonomy, complexity) VALUES
(1, 1, 1, 'Level 1: Follow', 'Assist with reading, questioning and communicating data in day-to-day decisions under close supervision, following documented procedures, on prepared datasets.', 'Works under close supervision within clearly defined procedures.', 'Routine tasks with predictable inputs.'),
(2, 1, 2, 'Level 2: Apply', 'Handle reading, questioning and communicating data in day-to-day decisions for routine cases with limited supervision, applying established standards, against agreed data quality rules.', 'Works with limited supervision on defined tasks.', 'Standard tasks with occasional variation.'),
(3, 1, 3, 'Level 3: Evaluate', 'Take responsibility for reading, questioning and communicating data in day-to-day decisions in complex or non-standard cases, exercising judgement and guiding less experienced staff, where sources conflict or are incomplete.', 'Works independently and checks the work of others.', 'Complex or non-standard cases requiring judgement.'),
(4, 1, 4, 'Level 4: Manage', 'Manage reading, questioning and communicating data in day-to-day decisions across a function, resolving escalations and setting local standards and controls, across the function’s data estate.', 'Accountable for a function or workstream and the people in it.', 'Ambiguous problems spanning several teams.'),
(5, 2, 1, 'Level 1: Follow', 'Assist with building and maintaining reports and dashboards for business users under close supervision, following documented procedures, on prepared datasets.', 'Works under close supervision within clearly defined procedures.', 'Routine tasks with predictable inputs.'),
(6, 2, 2, 'Level 2: Apply', 'Handle building and maintaining reports and dashboards for business users for routine cases with limited supervision, applying established standards, against agreed data quality rules.', 'Works with limited supervision on defined tasks.', 'Standard tasks with occasional variation.'),
(7, 2, 3, 'Level 3: Evaluate', 'Take responsibility for building and maintaining reports and dashboards for business users in complex or non-standard cases, exercising judgement and guiding less experienced staff, where sources conflict or are incomplete.', 'Works independently and checks the work of others.', 'Complex or non-standard cases requiring judgement.'),
(8, 2, 4, 'Level 4: Manage', 'Manage building and maintaining reports and dashboards for business users across a function, resolving escalations and setting local standards and controls, across the function’s data estate.', 'Accountable for a function or workstream and the people in it.', 'Ambiguous problems spanning several teams.'),
(9, 2, 5, 'Level 5: Lead', 'Lead building and maintaining reports and dashboards for business users across the organisation, setting strategy, standards and capability plans, as an enterprise data capability.', 'Accountable for the domain across the organisation.', 'Strategic problems with material risk and investment.'),
(10, 3, 2, 'Level 2: Apply', 'Handle applying statistical methods to answer defined business questions for routine cases with limited supervision, applying established standards, against agreed data quality rules.', 'Works with limited supervision on defined tasks.', 'Standard tasks with occasional variation.'),
(11, 3, 3, 'Level 3: Evaluate', 'Take responsibility for applying statistical methods to answer defined business questions in complex or non-standard cases, exercising judgement and guiding less experienced staff, where sources conflict or are incomplete.', 'Works independently and checks the work of others.', 'Complex or non-standard cases requiring judgement.'),
