(1421, 315, 3, 'Level 3: Evaluate', 'Take responsibility for opening and growing new geographic and segment markets in complex or non-standard cases, exercising judgement and guiding less experienced staff, in contested or high-value situations.', 'Works independently and checks the work of others.', 'Complex or non-standard cases requiring judgement.'),
(1422, 315, 4, 'Level 4: Manage', 'Manage opening and growing new geographic and segment markets across a function, resolving escalations and setting local standards and controls, for a portfolio or market.', 'Accountable for a function or workstream and the people in it.', 'Ambiguous problems spanning several teams.'),
(1423, 315, 5, 'Level 5: Lead', 'Lead opening and growing new geographic and segment markets across the organisation, setting strategy, standards and capability plans, for the commercial strategy.', 'Accountable for the domain across the organisation.', 'Strategic problems with material risk and investment.'),
(1424, 315, 6, 'Level 6: Direct', 'Set direction for opening and growing new geographic and segment markets at organisational and industry level, pioneering practice others adopt, shaping how the market operates.', 'Sets direction beyond the organisation; recognised authority.', 'Novel, unbounded problems shaping industry practice.'),
(1425, 316, 1, 'Level 1: Follow', 'Assist with executing trade documentation, settlement and shipment operations under close supervision, following documented procedures, on a single shift or task.', 'Works under close supervision within clearly defined procedures.', 'Routine tasks with predictable inputs.'),
(1426, 316, 2, 'Level 2: Apply', 'Handle executing trade documentation, settlement and shipment operations for routine cases with limited supervision, applying established standards, for a defined process.', 'Works with limited supervision on defined tasks.', 'Standard tasks with occasional variation.'),
(1427, 316, 3, 'Level 3: Evaluate', 'Take responsibility for executing trade documentation, settlement and shipment operations in complex or non-standard cases, exercising judgement and guiding less experienced staff, when the process breaks down.', 'Works independently and checks the work of others.', 'Complex or non-standard cases requiring judgement.'),
(1428, 316, 4, 'Level 4: Manage', 'Manage executing trade documentation, settlement and shipment operations across a function, resolving escalations and setting local standards and controls, across an operating unit.', 'Accountable for a function or workstream and the people in it.', 'Ambiguous problems spanning several teams.'),
(1429, 316, 5, 'Level 5: Lead', 'Lead executing trade documentation, settlement and shipment operations across the organisation, setting strategy, standards and capability plans, across the operating model.', 'Accountable for the domain across the organisation.', 'Strategic problems with material risk and investment.'),
(1430, 317, 3, 'Level 3: Evaluate', 'Take responsibility for assessing and limiting exposure to trading counterparties in complex or non-standard cases, exercising judgement and guiding less experienced staff, when the process breaks down.', 'Works independently and checks the work of others.', 'Complex or non-standard cases requiring judgement.'),
(1431, 317, 4, 'Level 4: Manage', 'Manage assessing and limiting exposure to trading counterparties across a function, resolving escalations and setting local standards and controls, across an operating unit.', 'Accountable for a function or workstream and the people in it.', 'Ambiguous problems spanning several teams.'),
(1432, 317, 5, 'Level 5: Lead', 'Lead assessing and limiting exposure to trading counterparties across the organisation, setting strategy, standards and capability plans, across the operating model.', 'Accountable for the domain across the organisation.', 'Strategic problems with material risk and investment.'),
(1433, 317, 6, 'Level 6: Direct', 'Set direction for assessing and limiting exposure to trading counterparties at organisational and industry level, pioneering practice others adopt, setting the benchmark for the sector.', 'Sets direction beyond the organisation; recognised authority.', 'Novel, unbounded problems shaping industry practice.');
INSERT INTO ccs_clusters (code, name, blurb) VALUES
('TC', 'Thinking Critically', 'Cognitive skills that let you see connections, frame problems and choose well under change.'),
('IO', 'Interacting with Others', 'Skills for working through other people: persuading, including, developing and serving.'),
('SR', 'Staying Relevant', 'Managing yourself and reading the signals that decide what to learn next.');
INSERT INTO ccs (id, code, title, description, cluster) VALUES
(1, 'CCS-CRT', 'Creative Thinking', 'Adopt a fresh perspective to generate and combine ideas that lead to new value.', 'TC'),
(2, 'CCS-DEC', 'Decision Making', 'Choose a course of action from available options using evidence, judgement and awareness of consequence.', 'TC'),
(3, 'CCS-PRB', 'Problem Solving', 'Define a problem accurately, find its causes and implement a solution that holds.', 'TC'),
(4, 'CCS-SEN', 'Sense Making', 'Interpret and analyse information to recognise patterns, meaning and opportunity.', 'TC'),
(5, 'CCS-TRD', 'Transdisciplinary Thinking', 'Draw on concepts from multiple disciplines to make decisions and solve problems that no single field covers.', 'TC'),
(6, 'CCS-BIN', 'Building Inclusivity', 'Manage relationships across diverse groups so that difference becomes an asset.', 'IO'),
(7, 'CCS-COL', 'Collaboration', 'Work with others towards a shared outcome, contributing and receiving in equal measure.', 'IO'),
(8, 'CCS-COM', 'Communication', 'Convey and receive information and intent accurately, in the form the audience needs.', 'IO'),
(9, 'CCS-CUS', 'Customer Orientation', 'Anticipate and meet the needs of internal and external customers to build lasting relationships.', 'IO'),
(10, 'CCS-DEV', 'Developing People', 'Help others build capability through coaching, feedback and deliberate opportunity.', 'IO'),
(11, 'CCS-INF', 'Influence', 'Shape the decisions and behaviour of others without relying on formal authority.', 'IO'),
(12, 'CCS-ADP', 'Adaptability', 'Adjust readily to changing conditions, expectations and ways of working.', 'SR'),
(13, 'CCS-DIG', 'Digital Fluency', 'Use the right digital tools across work processes to solve problems, drive efficiency and share information.', 'SR'),
(14, 'CCS-GLB', 'Global Perspective', 'Understand global and regional dynamics and work effectively across markets and cultures.', 'SR'),
(15, 'CCS-LAG', 'Learning Agility', 'Use different learning approaches to keep capability current and to learn faster from experience.', 'SR'),
(16, 'CCS-SLF', 'Self Management', 'Manage your own priorities, wellbeing and professional conduct to sustain performance.', 'SR');
INSERT INTO ccs_levels (id, ccs_id, band, band_name, descriptor, behaviours) VALUES
(1, 1, 1, 'Basic', 'Generate ideas within a defined brief and build on the suggestions of others.', '["Contributes ideas in structured sessions","Adapts an existing approach to a new task","Recognises when the usual method is not working"]'),
(2, 1, 2, 'Intermediate', 'Facilitate idea generation across a team and turn promising ideas into testable concepts.', '["Runs structured ideation with mixed groups","Prototypes and tests a concept before committing","Combines ideas from unrelated domains"]'),
(3, 1, 3, 'Advanced', 'Build an environment where original thinking is expected, resourced and converted into value.', '["Sets innovation direction and risk appetite","Sponsors experiments with unclear payoff","Removes structural barriers to new ideas"]'),
(4, 2, 1, 'Basic', 'Make routine decisions within clear parameters and escalate what falls outside them.', '["Applies decision rules consistently","Identifies who owns a decision","Documents the basis of a choice"]'),
(5, 2, 2, 'Intermediate', 'Weigh competing options under incomplete information and own the outcome.', '["Frames options with explicit trade-offs","Tests assumptions before deciding","Sets review points to correct course"]'),
(6, 2, 3, 'Advanced', 'Decide on high-stakes, irreversible matters and build decision quality into the organisation.', '["Allocates decision rights deliberately","Manages second-order and reputational consequence","Institutes post-decision review"]'),
(7, 3, 1, 'Basic', 'Resolve familiar problems using established methods and known escalation paths.', '["Describes a problem in factual terms","Applies a standard troubleshooting sequence","Checks that the fix actually worked"]'),
(8, 3, 2, 'Intermediate', 'Diagnose root causes of unfamiliar problems and design durable solutions.', '["Separates symptom from cause","Uses data to test candidate causes","Designs against recurrence, not just recovery"]'),
(9, 3, 3, 'Advanced', 'Resolve systemic and cross-boundary problems where the problem itself is contested.', '["Reframes problems that resist solution","Aligns parties with conflicting definitions","Redesigns systems to remove whole problem classes"]'),
(10, 4, 1, 'Basic', 'Organise information from given sources and summarise what it shows.', '["Distinguishes fact from inference","Spots obvious anomalies in data","Summarises findings without distortion"]'),
(11, 4, 2, 'Intermediate', 'Synthesise ambiguous and conflicting information into a defensible reading of the situation.', '["Triangulates across sources of varying quality","Names the uncertainty in a conclusion","Draws implications, not just observations"]'),
(12, 4, 3, 'Advanced', 'Read weak signals ahead of others and shape how the organisation interprets its environment.', '["Detects pattern shifts before they are obvious","Challenges prevailing organisational narratives","Builds shared interpretive frameworks"]'),
(13, 5, 1, 'Basic', 'Recognise where another discipline holds knowledge relevant to your work and seek it out.', '["Identifies the limits of own expertise","Asks informed questions of other specialists","Uses cross-domain vocabulary accurately"]'),
(14, 5, 2, 'Intermediate', 'Integrate methods from adjacent disciplines into your own practice and translate between them.', '["Borrows and adapts methods across fields","Translates specialist findings for other audiences","Runs mixed-discipline working groups"]'),
(15, 5, 3, 'Advanced', 'Lead work at the intersection of disciplines and create the conditions for it to succeed.', '["Frames problems that cut across professions","Builds teams around a problem, not a function","Resolves conflict between disciplinary standards"]'),
(16, 6, 1, 'Basic', 'Work respectfully with colleagues of different backgrounds and adjust your own behaviour.', '["Uses inclusive language as a default","Notices who is not being heard","Asks rather than assumes"]'),
(17, 6, 2, 'Intermediate', 'Design ways of working that let a diverse team contribute fully.', '["Adapts processes for different needs","Surfaces and addresses exclusion in the team","Mediates across cultural expectations"]'),
(18, 6, 3, 'Advanced', 'Set inclusion policy and hold the organisation to it.', '["Sets measurable inclusion outcomes","Removes structural bias in systems and criteria","Holds leaders accountable for inclusive practice"]'),
(19, 7, 1, 'Basic', 'Contribute reliably to a team, meeting commitments and sharing information.', '["Delivers what was agreed, on time","Shares information proactively","Asks for help before a problem grows"]'),
(20, 7, 2, 'Intermediate', 'Coordinate work across teams and resolve friction without escalation.', '["Negotiates interfaces between teams","Surfaces and settles disagreement early","Builds trust with partners outside own unit"]'),
(21, 7, 3, 'Advanced', 'Build partnerships across organisational boundaries and sustain them under strain.', '["Structures multi-party agreements","Aligns partners with divergent incentives","Keeps alliances working through conflict"]'),
(22, 8, 1, 'Basic', 'Communicate clearly in routine situations and check that you have been understood.', '["Writes and speaks without ambiguity","Listens for meaning, not just words","Confirms understanding before acting"]'),
(23, 8, 2, 'Intermediate', 'Adapt message, medium and framing to different audiences, including difficult ones.', '["Tailors technical content for non-specialists","Handles disagreement without escalation","Structures a case, not just facts"]'),
(24, 8, 3, 'Advanced', 'Communicate on behalf of the organisation on complex or contested matters.', '["Represents position under scrutiny","Sets communication strategy and standards","Manages message through crisis"]'),
(25, 9, 1, 'Basic', 'Serve customers within established standards and refer what you cannot resolve.', '["Follows service standards consistently","Records customer needs accurately","Escalates with full context"]'),
(26, 9, 2, 'Intermediate', 'Anticipate customer needs and improve the service based on what you observe.', '["Identifies unstated needs","Recovers a failed service experience","Feeds insight back into process change"]'),
(27, 9, 3, 'Advanced', 'Set customer strategy and design the operating model that delivers it.', '["Defines the service proposition","Balances customer value against cost to serve","Builds a customer-centred culture"]'),
(28, 10, 1, 'Basic', 'Support colleagues by sharing knowledge and giving specific, usable feedback.', '["Explains own work so others can repeat it","Gives feedback on behaviour, not person","Onboards new colleagues willingly"]'),
(29, 10, 2, 'Intermediate', 'Coach individuals against a development plan and create stretch opportunities.', '["Diagnoses a capability gap accurately","Delegates for development, not just load","Holds honest development conversations"]'),
(30, 10, 3, 'Advanced', 'Build organisational capability and succession ahead of need.', '["Plans succession for critical roles","Invests in capability before it is urgent","Develops other developers of people"]'),
(31, 11, 1, 'Basic', 'Present a reasoned case and respond to straightforward objections.', '["Backs a position with evidence","Understands the other party’s interest","Accepts a decision that goes the other way"]'),
(32, 11, 2, 'Intermediate', 'Build support across stakeholders with differing priorities.', '["Maps stakeholders and their interests","Sequences conversations to build momentum","Trades and concedes deliberately"]'),
(33, 11, 3, 'Advanced', 'Shape agendas and outcomes at senior and cross-organisational level.', '["Sets the terms of a debate","Builds coalitions across institutions","Influences through others over long horizons"]'),
(34, 12, 1, 'Basic', 'Adjust to changes in task and process with support, keeping performance steady.', '["Accepts changed priorities without disruption","Asks what the change means for own work","Recovers quickly from setbacks"]'),
(35, 12, 2, 'Intermediate', 'Reorganise your own and your team’s work in response to change and help others through it.', '["Re-plans quickly when conditions shift","Keeps others steady during change","Distinguishes what must change from what must not"]'),
(36, 12, 3, 'Advanced', 'Lead the organisation through discontinuous change and build resilience for the next one.', '["Prepares the organisation before change is forced","Sustains performance through transition","Designs for optionality and reversibility"]'),
(37, 13, 1, 'Basic', 'Use standard digital tools for daily work and follow data and security practice.', '["Works confidently in core workplace tools","Handles data according to policy","Recognises common digital risks"]'),
(38, 13, 2, 'Intermediate', 'Select and combine digital tools to improve a process, including automation and analysis.', '["Automates repetitive work","Interprets data to inform decisions","Evaluates a tool against a real need"]'),
(39, 13, 3, 'Advanced', 'Set digital direction for a function and lead adoption of new technology.', '["Prioritises digital investment against value","Leads change management for adoption","Governs data, AI and security standards"]'),
(40, 14, 1, 'Basic', 'Recognise how global and regional developments affect your own work.', '["Follows developments relevant to the sector","Works respectfully across cultures","Understands basic market differences"]'),
(41, 14, 2, 'Intermediate', 'Apply market and cultural understanding to decisions involving other countries.', '["Adapts practice for regional markets","Manages distributed and cross-border work","Assesses regulatory difference across markets"]'),
(42, 14, 3, 'Advanced', 'Set strategy that anticipates global shifts and positions the organisation across markets.', '["Reads geopolitical and trade risk","Sets market-entry and localisation strategy","Builds international partnerships"]'),
(43, 15, 1, 'Basic', 'Take up learning that is provided and apply it to your work.', '["Completes and applies assigned learning","Asks for feedback and acts on it","Keeps a record of what was learnt"]'),
(44, 15, 2, 'Intermediate', 'Direct your own learning against identified gaps and choose the right method for each.', '["Diagnoses own gaps against a target role","Chooses between course, practice and mentoring","Learns deliberately from failure"]'),
(45, 15, 3, 'Advanced', 'Build a learning culture and make capability renewal part of how the organisation runs.', '["Links learning investment to workforce strategy","Creates the conditions for on-the-job learning","Measures learning by capability change, not attendance"]'),
(46, 16, 1, 'Basic', 'Manage your own workload, time and conduct to meet expectations.', '["Plans and meets commitments","Maintains professional conduct under pressure","Recognises own stress signals"]'),
(47, 16, 2, 'Intermediate', 'Manage competing demands and sustain performance and wellbeing over time.', '["Prioritises against value, not urgency alone","Sets and holds boundaries","Seeks support before capacity is exceeded"]'),
(48, 16, 3, 'Advanced', 'Model and enable sustainable performance for a wider group.', '["Sets workload norms that hold","Acts on wellbeing signals in the team","Sustains judgement in prolonged pressure"]');
