INSERT INTO funding_schemes (code, name, kind, amount, rate, eligibility, note) VALUES
('BASE-SUB', 'SkillsFuture Course Fee Subsidy', 'subsidy', NULL, 0.7, 'Singapore Citizens and Permanent Residents, for approved courses.', 'Baseline subsidy of up to 70% of course fee.'),
('MCES', 'Mid-Career Enhanced Subsidy', 'subsidy', NULL, 0.9, 'Singapore Citizens aged 40 and above.', 'Up to 90% of course fee for eligible courses.'),
('SFC-OPEN', 'SkillsFuture Credit (Opening)', 'credit', 500, NULL, 'Singapore Citizens aged 25 and above.', 'One-off opening credit of $500; does not expire.'),
('SFC-MID', 'SkillsFuture Credit (Mid-Career)', 'credit', 4000, NULL, 'Singapore Citizens aged 40 and above, from 1 May 2024.', '$4,000 top-up for selected courses with strong employability outcomes; does not expire.'),
('SFTA-FT', 'SkillsFuture Mid-Career Training Allowance (Full-Time)', 'allowance', NULL, NULL, 'Singapore Citizens aged 40 and above on eligible full-time training.', '50% of average income over the preceding 12 months, minimum $300 and maximum $3,000 per month; 24-month lifetime cap across full-time and part-time.'),
('SFTA-PT', 'SkillsFuture Mid-Career Training Allowance (Part-Time)', 'allowance', NULL, NULL, 'Singapore Citizens aged 40 and above with earned income in the last 12 months.', 'Flat $300 per month for selected part-time training; extended from 1 March 2026. Counts to the same 24-month lifetime cap.');
